import {session, logout} from './auth.js';
export function publicHeader(icon){return `<header class="public-header"><a class="brand" href="#home" aria-label="StrataX home"><img src="logo.png" alt="StrataX logo"><span>StrataX</span></a><div class="actions">${session.user?'<a class="public-signin" href="#projects">Open workspace</a><button id="public-signout" class="quiet">Sign out</button>':'<a class="public-signin" href="#signin">Sign in</a><a class="button-link primary" href="#signup">Get started '+icon('arrow')+'</a>'}</div></header>`;}
export function footer(){return `<footer class="tc-footer"><div class="tc-shell tc-footer-main"><div class="tc-footer-brand"><a href="#home" aria-label="StrataX home"><img src="logo.png" alt="StrataX logo"><span>StrataX<small style="display:block;font-size:11px;margin-top:6px;font-weight:400">by TerraCode Analytics</small></span></a><p>Geoscience intelligence and cloud engineering from Lagos, Nigeria.</p><a class="tc-footer-email" href="mailto:contact@terracodeanalytics.com">contact@terracodeanalytics.com</a></div><nav class="tc-footer-nav" aria-label="Footer navigation"><div><h2>Explore</h2><a href="https://terracodeanalytics.com/gaia">GAIA</a><a href="https://terracodeanalytics.com/gorchestrate">G-Orchestrate</a><a href="https://terracodeanalytics.com/developers">Developers</a><a href="https://terracodeanalytics.com/services">Services</a></div><div><h2>Company</h2><a href="https://terracodeanalytics.com/partners">Partners</a><a href="https://terracodeanalytics.com/team">Team</a><a href="https://terracodeanalytics.com/blog">Blog</a><a href="https://terracodeanalytics.com/contact">Contact</a></div><div><h2>Follow</h2><a href="https://x.com/terra_analytics" target="_blank" rel="noopener noreferrer">X / Twitter ↗</a><a href="https://www.instagram.com/terracodeanalytics_/" target="_blank" rel="noopener noreferrer">Instagram ↗</a><a href="https://www.linkedin.com/company/terracode-analytics-limited-01/" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="https://www.youtube.com/@TerraCodeAnalytics" target="_blank" rel="noopener noreferrer">YouTube ↗</a></div></nav></div><div class="tc-shell tc-footer-legal"><span>© ${new Date().getFullYear()} Terracode Analytics Limited</span><nav aria-label="Legal links"><a href="#terms">Terms</a><a href="#privacy">Privacy</a><a href="#cookies">Cookies</a><a href="#acceptable-use">Acceptable Use</a><a href="#data-ownership">Data Ownership</a><a href="#ai-processing">AI Processing</a><a href="#disclaimer">Disclaimer</a></nav><span class="tc-footer-coordinate">06.5244° N · 03.3792° E</span></div></footer>`;}
export function renderLanding(icon,chart){document.querySelector('#app').innerHTML=`<div class="landing">${publicHeader(icon)}<main><section class="landing-hero"><div class="hero-copy"><span class="hero-category"><span class="dot"></span>SUBSURFACE INTERPRETATION WORKSPACE</span><h1>Know your data.<br>See what’s possible.</h1><p>A focused workspace for well data, petrophysical interpretation and evidence-led decisions. From your first legacy file to a reviewed reservoir study.</p><div class="hero-actions">${session.user?'<a class="button-link primary" href="#projects">Open workspace '+icon('arrow')+'</a>':'<a class="button-link primary" href="#signup">Get started '+icon('arrow')+'</a><a class="button-link" href="#signin">Sign in</a>'}</div><div class="hero-topics"><span>Well data & documents</span><span>Petrophysics</span><span>Spatial context</span></div></div><div class="hero-product"><div class="product-window-bar"><span class="window-dots">● ● ●</span><span>StrataX / Tomboy field / Interpretation</span><span class="badge green">Illustrative workspace</span></div><div class="hero-product-layout"><div class="hero-mini-nav"><img src="logo.png" alt=""><span class="mini-item">Overview</span><span class="mini-item">Data</span><span class="mini-item">Map</span><span class="mini-item selected">Interpretation</span><span class="mini-item">Reports</span></div><div class="hero-mini-workspace"><div class="hero-mini-heading"><div><small>WELL LOG WORKSPACE</small><h3>Evidence, in context.</h3></div><span class="badge gray">TMB-02</span></div><div class="hero-log-labels"><span>DEPTH</span><span>GAMMA RAY</span><span>RESISTIVITY</span><span>DENSITY</span><span>NEUTRON</span></div>${chart()}<div class="hero-mini-status"><span><i class="dot"></i>Original measurements preserved</span><span>Illustrative log tracks</span></div></div></div><div class="hero-floating-card">${icon('shield')}<span><strong>Every decision has a source.</strong><small>Review the evidence behind your interpretation.</small></span></div></div></section></main>${footer()}</div>`;bindPublic();}
export function bindPublic(){document.querySelector('#public-signout')?.addEventListener('click',async()=>{await logout();});}
